test("task_completed retains mutations when no verification command is available", async () => {
  const repo = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-worktree-no-tests-"));
  execSync("git init -q", { cwd: repo, stdio: "ignore" });
  execSync('git config user.name "Nexus Test" && git config user.email "nexus@example.invalid"', { cwd: repo, stdio: "ignore" });
  fs.writeFileSync(path.join(repo, "base.txt"), "base\n");
  execSync("git add . && git commit -qm baseline", { cwd: repo, stdio: "ignore" });
  const { discoverVerifier } = await import("../src/tester.js");
  assert.strictEqual(discoverVerifier(repo), null, "discoverVerifier returns null when no verification command is available");

  let requests = 0;
  const server = http.createServer((req, res) => {
    if (req.headers["x-nexus-purpose"] === "capabilities") { res.setHeader("content-type", "application/json"); res.end('{"data":[]}'); return; } // capability discovery: no catalog
    requests++;
    let body = "";
    req.on("data", (chunk) => { body += chunk; });
    req.on("end", () => {
      const toolCalls = requests === 1 ? [
        { index: 0, id: "write", type: "function", function: { name: "write_file", arguments: JSON.stringify({ path: "unverified.txt", content: "retain me\n" }) } },
        { index: 1, id: "complete", type: "function", function: { name: "task_completed", arguments: JSON.stringify({ summary: "Claimed complete without a test suite." }) } },
      ] : [];
      res.writeHead(200, { "Content-Type": "text/event-stream" });
    if (this.activeWorktree?.kind === "named") {
      console.log(pc.cyan(`🌲 Named worktree ${this.activeWorktree.branch} kept at ${this.activeWorktree.worktreePath}. Merge it with \`nexus worktree merge\` from inside it, or remove it with \`nexus worktree remove\`.`));
    } else if (this.activeWorktree && this.config.worktree) {
      const hasChanges = this.worktreeManager.hasChanges(this.activeWorktree.taskId);
      if (hasChanges) {
        if (
          this.activeValidationReceipt &&
          !this.worktreeManager.rootHasChanges() &&
          !this.worktreeManager.hasIgnoredChanges(this.activeWorktree.taskId)
        ) {
          console.log(pc.cyan(`🌲 Merging verified changes from worktree ${this.activeWorktree.branch}...`));
          const result = this.mergeActiveWorktree(
            `nexus: apply verified changes from ${this.activeWorktree.taskId}`,
            this.activeValidationReceipt
          );
          if (!result.success) {
            console.log(pc.yellow(`⚠️ Worktree retained because merge was refused: ${result.error || "unknown error"}`));
          }
        } else {
          console.log(pc.yellow(`⚠️ Speculative changes are unverified or the root workspace is dirty; retaining worktree at ${this.activeWorktree.worktreePath}`));
        }
      } else {
        this.discardActiveWorktree();
      }
    }
  }
  if (!turnResult) throw new Error("Turn ended without a result");
  return turnResult;
}

